<?php
require_once '../config/db.php'; require_once '../includes/auth.php'; require_role(['Admin','Property Officer']);
$properties=$pdo->query("SELECT p.id,p.property_code,p.property_no,p.scheme_name,p.price,p.category,p.property_type FROM properties p LEFT JOIN allottees a ON a.property_id=p.id WHERE a.id IS NULL ORDER BY p.created_at DESC")->fetchAll();
?><!DOCTYPE html><html lang="en"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Enrollment Update</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><link href="../assets/css/style.css" rel="stylesheet"></head><body><div class="portal-wrapper"><header class="portal-header"><div class="portal-brand">✅ Enrollment Update</div><div class="portal-header-actions"><a href="admin.php" class="btn btn-sm btn-outline-light">Dashboard</a><a href="../logout.php" class="btn btn-sm btn-light">Logout</a></div></header><main class="portal-main"><div class="portal-page-header"><h1 class="portal-page-title">Enrollment / Allotment</h1><p class="portal-page-subtitle">Vacant property select karke allottee details भरें.</p></div><div class="dashboard-shell table-responsive"><table class="table align-middle"><thead><tr><th>S.No.</th><th>Property</th><th>Scheme</th><th>Type</th><th>Price</th><th>Action</th></tr></thead><tbody><?php foreach($properties as $i=>$p): ?><tr><td><?= $i+1 ?></td><td><strong><?= htmlspecialchars($p['property_code']) ?></strong><br><?= htmlspecialchars($p['property_no']) ?></td><td><?= htmlspecialchars($p['scheme_name']) ?></td><td><?= htmlspecialchars($p['property_type']??'Residential') ?><br><small><?= htmlspecialchars($p['category']) ?></small></td><td>₹<?= number_format($p['price'],2) ?></td><td><a href="add_allottee.php?property_id=<?= $p['id'] ?>" class="btn btn-sm btn-primary">Allot Property</a></td></tr><?php endforeach; ?><?php if(!$properties): ?><tr><td colspan="6" class="text-center text-muted">No vacant properties available.</td></tr><?php endif; ?></tbody></table></div></main></div></body></html>
